/**
 * Taskop's colour system (design note: docs/superpowers/specs/2026-10-15-redesign-design-direction.md).
 * The web app and the landing page read these through tokens.css (generated by `pnpm --filter @taskop/brand generate`);
 * the mobile app imports them from here. Every pair listed in the design note meets WCAG AA.
 */

/** Surfaces and text of one colour scheme. */
export interface SchemeTokens {
  /** The page behind everything. */
  canvas: string;
  /** Cards, tables, inputs, dialogs. */
  surface: string;
  /** A raised surface: popovers, the mobile header block in dark mode. */
  surfaceRaised: string;
  /** Primary text. */
  ink: string;
  /** Secondary text: labels, captions, placeholders. */
  ink2: string;
  /** Borders and dividers. */
  line: string;
  /** A stronger border: inputs, focused cards. */
  lineStrong: string;
  /** Primary actions, links, the in-progress state. */
  primary: string;
  /** Hover and pressed primary. */
  primaryDeep: string;
  /** Text on primary. */
  onPrimary: string;
  /** Tinted background for primary chips and selected rows. */
  primarySoft: string;
  /** The deep brand surface: the web sidebar and the mobile headers. */
  deep: string;
  /** Text on `deep`. */
  onDeep: string;
  /** Secondary text on `deep`. */
  onDeepMuted: string;
  /** Brand accent: the logo variant, the landing page, the current-page tick. Never a status colour. */
  saffron: string;
  /** The focus ring. */
  focus: string;
}

/** One status colour: `solid` for icons and bars, `text` for words on `soft`, `soft` for chip and banner backgrounds. */
export interface StatusTokens {
  solid: string;
  text: string;
  soft: string;
}

export type StatusKey = 'planned' | 'active' | 'ok' | 'late' | 'bad' | 'audit';

export interface ColorTokens extends SchemeTokens {
  status: Record<StatusKey, StatusTokens>;
}

